function quickFilterProcess(){$('#more_filter_form [name="title"]').val($('.box-filter .bar-filter [name="title"]').val());$('#more_filter_form [name="status"]').val($('.box-filter .bar-filter [name="status"').val());$("#more_filter_form").submit()}function showAddTagPopup(){showPopup('<p>لطفا عنوان تگ جدید را وارد کرده و روی دکمه «ثبت» کلیک کنید:<\/p><div class="add-tag-operation"><input type="text" id="new_tag_title" class="text-input" /><button onclick="addNewTag()" type="button" class="btn">ثبت<\/button><\/div>')}function addNewTag(){let n=$("#new_tag_title").val();if(!n){errorAlert("لطفا عنوان تگ جدید را وارد کنید");return}sendPostAjax("/tags/add",{title:n},function(){location.reload()},null,hidePopup)}function activeTag(n,t){showConfirm("آیا از تایید این تگ مطمئنید؟",function(){sendPostAjax("/tags/activate",{id:n},function(){$(t).css("color","limegreen");successAlert("تگ مورد نظر با موفقیت تایید شد")})})}function showEditPopup(n,t){showPopup('<p>لطفا عنوان جدید را وارد کرده و روی دکمه «ثبت» کلیک کنید:<\/p><div class="add-tag-operation">'+`<input type="hidden" id="edited_tag_id" value="${n}" /> `+`<input type="text" id="edited_tag_title" class="text-input" value="${t}" /> `+'<button onclick="editTagTitle()" type="button" class="btn">ثبت<\/button><\/div>')}function editTagTitle(){let t=$("#edited_tag_id").val(),n=$("#edited_tag_title").val();if(!n){errorAlert("لطفا عنوان تگ جدید را وارد کنید");return}sendPostAjax("/tags/edittitle",{id:t,title:n},function(){$(`#js-${t} .column-title`).html(n);$(`#js-${t} .column-urltitle`).html(n);successAlert("تگ مورد نظر با موفقیت ویرایش شد")},null,hidePopup)}function deleteTag(n){showConfirm("آیا از حذف این تگ مطمئنید؟",function(){sendPostAjax("/tags/delete",{id:n},function(){$("#js-"+n).remove();successAlert("تگ مورد نظر با موفقیت حذف شد")})})}